<div class="table-scroll"><table><thead><tr><th>Participante</th><th>Ingresso / etiqueta</th><th>Pagamento</th><th>Entrada</th><th>Ações</th></tr></thead><tbody><?php if(!$orders):?><tr><td colspan="5" class="empty">Nenhum ingresso encontrado.</td></tr><?php endif;?><?php foreach($orders as $o):?><tr><td><b><?=e($o['name'])?></b><small><?=e($o['email'])?> · <?=e($o['cpf'])?></small></td><td><code><?=e($o['ticket_code'])?></code><?php if(!empty($o['ticket_label'])):?><span class="ticket-label"><?=e($o['ticket_label'])?></span><?php endif;?><?php if(!$o['active']):?><i>INATIVO</i><?php endif;?></td><td><span class="status <?=e($o['status'])?>"><?=['paid'=>'Pago','pending'=>'Pendente','cancelled'=>'Cancelado'][$o['status']]??e($o['status'])?></span></td><td><?=$o['checked_in_at']?'<b class="ok">✓ '.e($o['checked_in_at']).'</b>':'—'?></td><td><div class="row-actions"><a href="?edit=<?=$o['id']?>">Editar</a><a href="label.php?id=<?=$o['id']?>" target="_blank">Etiqueta</a><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$o['id']?>"><input type="hidden" name="return_tab" value="tickets"><?php if($o['status']!=='paid'):?><button name="action" value="pay">Aprovar</button><?php elseif(!$o['checked_in_at']&&$o['active']):?><button name="action" value="checkin">Check-in</button><?php endif;?><button name="action" value="resend">Reenviar</button><button class="danger" name="action" value="toggle"><?=$o['active']?'Inativar':'Reativar'?></button></form></div></td></tr><?php endforeach;?></tbody></table></div>
